   walkPoints=List.of(new BlockPos(10,18,-3),new BlockPos(10,18,8),new BlockPos(10,18,4),new BlockPos(-2,18,4),new BlockPos(-6,18,4),new BlockPos(-2,18,4),new BlockPos(-2,-4,27),new BlockPos(-8,-5,27),new BlockPos(-8,-5,10),new BlockPos(6,-5,10),new BlockPos(-8,-5,10),new BlockPos(-8,-5,-8),new BlockPos(7,-5,-8),new BlockPos(7,-5,-7),new BlockPos(10,-5,-7),new BlockPos(10,1,1),new BlockPos(10,1,7));
