 private static Map<String,Object> trap()throws Exception {var plate=piece.local(10,-11,10);var s=level.getBlockState(plate);if(s.is(Blocks.STONE_PRESSURE_PLATE)&&s.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.POWERED))platePowered=true;for(var e:level.getEntitiesOfClass(PrimedTnt.class,AABB.of(piece.getBoundingBox())))primed.add(e.getUUID());playerHurt|=player.getHealth()<initialHealth||player.isDeadOrDying();if(ticks<220)return null;require(platePowered,"Actual connected player powers original native stone pressure plate");require(primed.size()==9,"All nine native TNT blocks prime from actual plate/explosion chain: "+primed.size());require(tnt()==0,"Actual native explosion consumes all original TNT");require(playerHurt&&player.isDeadOrDying(),"Actual survival player is killed by original pyramid trap");report.put("isolatedNativeTrap",Map.of("plateActuallyPowered",platePowered,"uniquePrimedTNT",primed.size(),"remainingTNT",tnt(),"survivalPlayerDamaged",playerHurt,"survivalPlayerDead",player.isDeadOrDying(),"ticks",ticks,"disposableCopyOnly",true));Files.writeString(dir.resolve("native-trap-result.json"),GSON.toJson(report));phase=99;return report;}
 private static Map<String,Object> verify(ServerLevel l,ReimaginedLayoutPiece p,Path d,boolean r)throws Exception {var result=new LinkedHashMap<String,Object>();var tag=p.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(l));boolean legacy=tag.getIntOr("PyramidReplacement",0)==0;result.put("legacy",legacy);result.put("replacementDefinition",tag.getIntOr("PyramidReplacement",0));String reference=System.getProperty("blockbranch.pyramidReplacementReference","");require(!reference.isEmpty(),"Explicit authentic212 reference");int checked=0,plants=0;
  try(var rows=Files.lines(Path.of(reference).resolve("native-site.voxels.jsonl"))){for(String line:(Iterable<String>)rows::iterator){var row=com.google.gson.JsonParser.parseString(line).getAsJsonObject();int x=row.get("x").getAsInt(),y=row.get("y").getAsInt(),z=row.get("z").getAsInt();if(!legacy&&(x<0||x>20||z<0||z>20||y< -14||y>16))continue;String expected=row.get("state").getAsString();if(!legacy&&(expected.startsWith("Block{minecraft:cactus}")||expected.equals("Block{minecraft:dead_bush}"))){expected="Block{minecraft:cave_air}";plants++;}if(!legacy)expected=observationExpected(expected,x,y,z);if(!legacy&&r&&x==15&&y==0&&z==14)expected="Block{minecraft:sand}";String actual=PyramidGalleryQualification.architecturalState(l.getBlockState(p.local(x,y,z))).toString();require(expected.equals(actual),"Exact protected pyramid state "+x+","+y+","+z+" old="+expected+" actual="+actual);checked++;}}
  chests=new ArrayList<>();int archaeology=0;for(int y=-14;y<=16;y++)for(int z=0;z<=20;z++)for(int x=0;x<=20;x++){var at=p.local(x,y,z);if(l.getBlockEntity(at)instanceof ChestBlockEntity c)chests.add(c);if(l.getBlockState(at).is(Blocks.SUSPICIOUS_SAND))archaeology++;}require(chests.size()==4&&tnt()==9&&l.getBlockState(p.local(10,-11,10)).is(Blocks.STONE_PRESSURE_PLATE),"Original four chests/nine TNT/one plate");require(archaeology==(r&&!legacy?6:7),"Original archaeology count except explicit player brush");result.put("declaredObservationCells",legacy?0:108);result.put("strictComparedCells",checked);result.put("naturalPlantCleanupCells",plants);result.put("nativeChests",4);result.put("nativeTNT",9);result.put("nativeArchaeology",archaeology);result.put("nativeRouteNodes",ReimaginedRoutes.verify(l,p));var codec=PyramidGalleryQualification.codec(l);require(((Number)codec.get("independentRoundTrips")).intValue()==75&&((Number)codec.get("actualCurrent212Readers")).intValue()==1&&((Number)codec.get("actualCurrent213Readers")).intValue()==1,"Actual seventy-five registry cases and archived212/213 readers");result.put("codec",codec);
  if(!r||legacy){var baseline=com.google.gson.JsonParser.parseString(Files.readString(Path.of(reference).resolve("native-anatomy.json"))).getAsJsonObject();int entities=0;for(var feature:baseline.getAsJsonArray("features")){var f=feature.getAsJsonObject();if(f.get("blockEntity").getAsString().isEmpty())continue;var a=f.getAsJsonArray("local");var at=p.local(a.get(0).getAsInt(),a.get(1).getAsInt(),a.get(2).getAsInt());var be=l.getBlockEntity(at);require(be!=null&&be.saveWithFullMetadata(l.registryAccess()).toString().equals(f.get("blockEntityNBT").getAsString()),"Original native block entity loot table and seed exact "+at);entities++;}result.put("exactNativeLootTableSeedEntities",entities);}return result;
 }
 private static String observationExpected(String original,int x,int y,int z){
  if(x<0||x>8||y< -6||y> -3||z<9||z>11)return original;
  if(x==8&&(y==-5||y==-4)){require(original.startsWith("Block{minecraft:iron_bars}"),"Original native observation bars");return original;}
  if(y==-6){if(z==10&&x<=7)return x%3==1?"Block{minecraft:chiseled_sandstone}":"Block{minecraft:orange_terracotta}";return x==6||x==7?"Block{minecraft:orange_terracotta}":"Block{minecraft:cut_sandstone}";}
  if(x==1||x==4||x==6){if(z==9||z==11)return y==-4?"Block{minecraft:cut_sandstone}":"Block{minecraft:chiseled_sandstone}";if(y==-3)return "Block{minecraft:chiseled_sandstone}";}
  return "Block{minecraft:cave_air}";
 }
 private static void saved()throws Exception {var witness=new LinkedHashMap<String,Object>();witness.put("uuid",player.getUUID().toString());witness.put("inventory",items(player.getInventory()));witness.put("inventoryItems",count(player.getInventory()));witness.put("repair",state(local(REPAIR)));witness.put("brushState",state(brushTarget()));witness.put("emptyNativeChests",chests.stream().filter(c->c.getLootTable()==null&&count(c)==0).count());var bes=new ArrayList<Object>();for(int y=-14;y<=16;y++)for(int z=0;z<=20;z++)for(int x=0;x<=20;x++){var at=piece.local(x,y,z);var be=level.getBlockEntity(at);if(be!=null)bes.add(Map.of("local",List.of(x,y,z),"nbt",be.saveWithFullMetadata(level.registryAccess()).toString()));}witness.put("nativeBlockEntityNBT",bes);require(((Number)witness.get("emptyNativeChests")).intValue()==4,"All four native chests remain consumed");var file=dir.resolve("native-player-witness.json");if(reopen){require(GSON.toJsonTree(witness).equals(com.google.gson.JsonParser.parseString(Files.readString(file))),"Exact full player UUID/inventory, brush loot, four consumed chests, archaeology NBT and repair persist");}else Files.writeString(file,GSON.toJson(witness));report.put("playerSaveWitness",witness);}
