 private static BlockPos local(BlockPos p){return piece.local(p.getX(),p.getY(),p.getZ());}private static String state(BlockPos at){return PyramidGalleryQualification.architecturalState(level.getBlockState(at)).toString();}
 private static int tnt(){int n=0;for(int z=9;z<=11;z++)for(int x=9;x<=11;x++)if(level.getBlockState(piece.local(x,-13,z)).is(Blocks.TNT))n++;return n;}
 private static void move(int x,int y,int z,double extra,BlockPos aim){var at=piece.local(x,y,z);double cx=at.getX()+.5,cy=at.getY()+extra,cz=at.getZ()+.5;String rotation="";if(aim!=null){double dx=aim.getX()+.5-cx,dz=aim.getZ()+.5-cz,dy=aim.getY()+.8-(cy+player.getEyeHeight());rotation=" "+Math.toDegrees(Math.atan2(-dx,dz))+" "+Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz)));}level.getServer().getCommands().performPrefixedCommand(level.getServer().createCommandSourceStack(),"tp "+player.getName().getString()+" "+cx+" "+cy+" "+cz+rotation);player.setDeltaMovement(Vec3.ZERO);}
 private static int count(Container c){int n=0;for(int i=0;i<c.getContainerSize();i++)n+=c.getItem(i).getCount();return n;}private static Object item(ItemStack stack){return ItemStack.CODEC.encodeStart(net.minecraft.resources.RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,level.registryAccess()),stack).getOrThrow();}private static List<Object> items(Container c){var out=new ArrayList<Object>();for(int i=0;i<c.getContainerSize();i++)if(!c.getItem(i).isEmpty())out.add(Map.of("slot",i,"item",item(c.getItem(i))));return out;}
